// Shared helper — scales a zone's max font-size down for long phrases and
// for wide/heavy display fonts, so text never overflows its print area.
function fitFontSize(maxSize, text, font) {
  const len = text.length;
  const lengthFactor = len > 18 ? 0.68 : len > 12 ? 0.82 : 1;
  return Math.round(maxSize * (font.scale ?? 1) * lengthFactor);
}

