// ─── GARMENT MOCKUP ──────────────────────────────────────────────────────────

function TeeMockup({ color, text, font, fontColor, placement }) {
  const view  = placement === "Full Back" ? "back" : "front";
  const photo = color.hasPhoto ? MOCKUP_IMAGES[`tee_${color.name.toLowerCase()}_${view}`] : null;

  // No live photo for this colour (e.g. Charcoal) — fall back to the
  // colour-accurate flat illustration instead of showing the wrong garment.
  if (!photo) {
    return (
      <div>
        <TeeMockupIllustrated colorHex={color.hex} text={text} font={font} fontColor={fontColor} placement={placement}/>
        <p style={{ ...mono, fontSize:10, color:LEATHER, marginTop:10, textAlign:"center", letterSpacing:0.5, fontStyle:"italic" }}>
          Live photo preview isn't available in {color.name} yet — shown as a colour-accurate illustration. Same fit, same print.
        </p>
      </div>
    );
  }

  // Placement zones as % of the photo — calibrated to OTC's flat-lay shots
  // (garment-only, no model).
  const zones = {
    "Left Chest":  { left:32, top:21, width:16, height:12, fs: fitFontSize(13, text, font) },
    "Right Chest": { left:55, top:21, width:16, height:12, fs: fitFontSize(13, text, font) },
    "Full Front":  { left:27, top:18, width:46, height:44, fs: fitFontSize(24, text, font) },
    "Full Back":   { left:27, top:16, width:46, height:46, fs: fitFontSize(24, text, font) },
  };
  const z = zones[placement] || zones["Full Front"];

  return (
    <div style={{ position:"relative", width:"100%", lineHeight:0, borderRadius:10, overflow:"hidden" }}>
      <img src={photo} alt={`${color.name} tee — ${view}, flat lay`} style={{ width:"100%", display:"block" }}/>
      <div style={{
        position:"absolute", left:`${z.left}%`, top:`${z.top}%`, width:`${z.width}%`, height:`${z.height}%`,
        display:"flex", alignItems:"center", justifyContent:"center", padding:"3%", pointerEvents:"none",
      }}>
        <span style={{
          fontFamily:font.family, color:fontColor, fontSize:z.fs, lineHeight:1.2,
          textAlign:"center", wordBreak:"break-word",
          textShadow: fontColor==="#FAF9F5" ? "0 1px 3px rgba(0,0,0,0.4)" : "0 1px 2px rgba(255,255,255,0.15)",
        }}>{text}</span>
      </div>
    </div>
  );
}

